/**
 * 负责共用参与者的原生命、Role 与私有容器引用捕获和晚复验。输入为原 World／玩家 ID，
 * 输出保留原可写快照及当前性布尔值；不写 World、资源、阶段或领域许可。
 * 只复用原生命版本规则，Role 字段按原普通属性读取；getter／Proxy 可执行并按原时点抛错。
 * 不读取 Camp 组件、不校验枚举／JSON／完整槽、不建立 brand 或冻结快照；严格原体契约另有所有者。
 */
import { COMPONENT } from "./components/names";
import type { RoleComponent } from "./components/role";
import type { World } from "./world";
import { captureNightLife, livingNightLife, type NightLifeScope } from "./night_effects";

/** 保原可写顶层字段与组件引用；camp 是捕获的 Role.camp 值，不是 Camp 组件或独立行动权限。 */
export interface OriginalParticipant {
  life: NightLifeScope;
  role: RoleComponent;
  roleId: RoleComponent["role"];
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
}
/** 原生命先捕获，再查询 Role；仅两者存在才按 role→camp→privateState 读取，不复制或提前取字段。 */
export function captureOriginalParticipant(world: World, id: number): OriginalParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  return life && role
    ? { life, role, roleId: role.role, camp: role.camp, state: role.privateState }
    : null;
}
/** 生命／版本先短路，再核同 Role 引用及原三个字段；不新增 descriptor、Camp 引用或状态内容检查。 */
export function sameOriginalParticipant(world: World, snapshot: OriginalParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    snapshot.role.role === snapshot.roleId &&
    snapshot.role.camp === snapshot.camp &&
    snapshot.role.privateState === snapshot.state
  );
}

/**
 * 捕获原角色、生命、状态、来源及政策身份的夜能力 owner。输入为已选择实例与阶段当前性
 * 回调；输出为原体当前性和行动资格检查。替换原槽或政策仍撤销 scope，不写状态或付款。
 * isOwnerCurrent 保原已付效果复验，不因运行授权墓碑失效；仅 isEligible 在原复验后拒绝退休演员。
 * 查验政策身份字节由该状态族的唯一 codec 在原表达式位置生成，生命、id、来源及允许
 * 首次死亡的版本判断仍只在此 owner，不因 payload 合法而重新授权。
 */
import type { NightAbilityKind } from "@ai-werewolf-arena/game-contract";

import { captureRadiantTurn } from "./radiant_eclipse/night_frame";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import { COMPONENT } from "../../../core/domain/components/names";

import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { World } from "../../../core/domain/world";
import type { EntityId } from "../../../core/domain/model";
import { activeNightAbility, type NightAbilityReadView } from "./abilities";
import { aliveLifeVersion } from "../../../core/domain/components/alive";

import { DREAMER_STATE_SLOT } from "./dreamer/ports";
import { SHELTER_STATE_SLOT } from "./radiant_eclipse/shelter-state-slot";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";
import { ROLE_INSPECTION_STATE_SLOT } from "./role_inspection/ports";

/** 即使库存对象仍同一引用，政策编辑也会改变授权身份。 */
function policyIdentity(ability: NightAbilityReadView): string {
  switch (ability.kind) {
    case "pair_check":
      return JSON.stringify([ability.state.policy]);
    case "shelter":
      return SHELTER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "seer_check":
      return SEER_STATE_SLOT.invalidations.policyIdentity(ability);
    case "potion":
      return WITCH_STATE_SLOT.invalidations.policyIdentity(ability);
    case "guard":
      return GUARD_STATE_SLOT.invalidations.policyIdentity(ability);
    case "role_check":
      return ROLE_INSPECTION_STATE_SLOT.checkpoint.policyIdentity(ability);
    case "dream":
      return DREAMER_STATE_SLOT.invalidations.policyIdentity(ability);
  }
}

/** 请求动作前先捕获；只读资格仍在实际提交时重检，不因捕获而冻结演员。 */
export function captureNightAbilityScope<K extends NightAbilityKind>(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<K>,
  day: number,
  phaseCurrent: () => boolean,
) {
  const role = world.getComponent(actorId, COMPONENT.Role),
    life = captureNightLife(world, actorId);
  if (!role || !life) return null;
  const radiantCurrent = captureRadiantTurn(world, actorId, ability, day);
  const roleKind = role.role,
    camp = role.camp,
    privateState = role.privateState;
  const state = ability.state,
    kind = ability.kind,
    activation = ability.activation,
    id = ability.id;
  const source = ability.source,
    sourceKind = source.kind,
    sourceOwner = source.kind === "native" ? source.role : source.actorId,
    sourceId = source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined;
  const policy = policyIdentity(ability);
  const starts = ability.startsOnDay,
    expires = ability.expiresAfterDay,
    maxUses = ability.maxUses,
    disclosed = ability.sourceDisclosed;
  const ownerCurrent = (allowFirstDeath = false) =>
    phaseCurrent() &&
    world.getComponent(actorId, COMPONENT.Role) === role &&
    role.role === roleKind &&
    role.camp === camp &&
    role.privateState === privateState &&
    (livingNightLife(world, life) ||
      (allowFirstDeath &&
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        !life.life.alive &&
        aliveLifeVersion(life.life) === life.version + 1)) &&
    ability.id === id &&
    ability.kind === kind &&
    ability.activation === activation &&
    ability.state === state &&
    policyIdentity(ability) === policy &&
    (
      (role.privateState as { readonly abilities?: unknown }).abilities as
        Readonly<Record<string, NightAbilityReadView>> | undefined
    )?.[id] === ability &&
    ability.source === source &&
    source.kind === sourceKind &&
    (source.kind === "native" ? source.role : source.actorId) === sourceOwner &&
    (source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined) ===
      sourceId &&
    ability.startsOnDay === starts &&
    ability.expiresAfterDay === expires &&
    ability.maxUses === maxUses &&
    ability.sourceDisclosed === disclosed;
  return {
    role,
    life,
    state,
    isOwnerCurrent: ownerCurrent,
    isEligible: () =>
      radiantCurrent() &&
      ownerCurrent() &&
      // 原体仍可能服务已付效果；墓碑只阻止新的行动资格，不改 ownerCurrent 或资源数据。
      !isRoleExecutionRetired(role) &&
      activeNightAbility(role, kind, day, id) === ability,
  };
}

/**
 * 负责觉醒隐狼原激活学习枪贡献的装配。输入为原死亡波与晚查询；输出为含激活元数据复验的原枪击提案。
 * 捕获表每次 hook 独立创建；资源 owner 核原 state／learning／gun，不复制库存或复活已消费枪。
 * 查询函数在原 callee 点取得并裸调用；此装配不授许可、不标死或切换阶段，付款／失败由完整结算处理。
 * 在原有序死亡钩子时点只装配原读写贡献；许可与生命仍由结算复验，失败不补偿已付款库存。
 */
import { Role, permitsDeathShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { resolveNativeDeathShots } from "../native-death-shot-settlement";
import { getAwakenedState } from "./state";
import { createAwakenedGunReader } from "../native-death-gun-resources";

export const awakenedDeathHook: DeathHook = (world, ids, sources, choose, events, context) => {
  const readGun = createAwakenedGunReader({ get getAwakenedState() { return getAwakenedState; } });
  return resolveNativeDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.AwakenedHiddenWolf,
      state: readGun,
      permits: permitsDeathShot,
      shotEvent: (actorId, targetId) => ({
        timestamp: Date.now(),
        type: "player_shot",
        payload: { actorId, targetId },
      }),
    },
    context,
  );
};

/**
 * Checks and records Awakened Hidden Wolf knife inheritance from the actual surviving wolf
 * roster. Inputs are the World, night/day and original role state; outputs are eligibility or
 * the existing inheritance fact. No provisional death proposal grants the knife, and role/camp
 * identity is not rewritten.
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { currentAwakenedNight } from "./night_scope";
import { awakenedKnifeReady, getAwakenedState, recordAwakenedInheritance } from "./state";

export function canAwakenedKnife(role: RoleComponent, world?: World): boolean {
  const state = getAwakenedState(role),
    night = world && currentAwakenedNight(world, role);
  if (
    !world ||
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    night == null ||
    !awakenedKnifeReady(state, night)
  )
    return false;
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf);
  return wolves.length === 1 && world.getComponent(wolves[0]!, COMPONENT.Role) === role;
}
/** Only assembly and completed actual death proposals create persistent inheritance. */
export function refreshAwakenedInheritance(world: World, day: number, events: GameEvent[]): void {
  const wolves = world
    .getAliveEntityIds()
    .filter((id) => world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf);
  if (wolves.length !== 1) return;
  const actorId = wolves[0]!,
    role = world.getComponent(actorId, COMPONENT.Role)!,
    state = getAwakenedState(role);
  if (role.role !== Role.AwakenedHiddenWolf || !state || !recordAwakenedInheritance(state, day))
    return;
  events.push({
    timestamp: Date.now(),
    type: "awakened_inherited",
    payload: { actorId, day, firstKnifeNight: state.firstKnifeNight! },
  });
}

/**
 * Captures Awakened Hidden Wolf owner, mimic skill and mirror scopes for one real night. Inputs
 * are the original ability and role/life references; outputs are currentness checks and
 * night-commit bookkeeping. It never lets a new state, source or body inherit the old captured
 * permission.
 */
import type {
  AwakenedReadState as AwakenedState,
  AwakenedReadActiveSkill as AwakenedActiveSkill,
} from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { awakenedSkillForNight, getAwakenedState } from "./state";
import { findNightAbility, type NightAbilityReadView } from "../abilities";

export interface AwakenedOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: AwakenedState;
  readonly life: NightLifeScope;
  isCurrent(allowFirstDeath?: boolean): boolean;
}
export function captureAwakenedOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): AwakenedOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = getAwakenedState(role),
    life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    isCurrent: (allowFirstDeath = false) => {
      const original =
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        aliveLifeVersion(life.life) ===
          life.version + (allowFirstDeath && !life.life.alive ? 1 : 0);
      return (
        phaseCurrent() &&
        world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.AwakenedHiddenWolf &&
        role.camp === Camp.Wolf &&
        role.privateState === privateState &&
        getAwakenedState(role) === state &&
        original &&
        (allowFirstDeath || life.life.alive)
      );
    },
  };
}
/** Bind paid facts without reading a closed slot or spent bottle/knife. */
export function bindAwakenedSkill(
  owner: AwakenedOwnerScope,
  day: number,
): { readonly skill: AwakenedActiveSkill; isCurrent(allowFirstDeath?: boolean): boolean } | null {
  const learned = owner.state.learned,
    skill = awakenedSkillForNight(owner.state, day);
  if (
    !owner.isCurrent() ||
    !learned ||
    !skill ||
    learned.activationNight === null ||
    learned.activeFromNight === null
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    kind = skill.kind;
  return {
    skill,
    isCurrent: (allowFirstDeath = false) =>
      owner.isCurrent(allowFirstDeath) &&
      owner.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      learned.targetId === targetId &&
      learned.role === role &&
      learned.day === learnedDay &&
      learned.activationNight === activationNight &&
      learned.activeFromNight === activeFromNight,
  };
}
/** Only the Aw-owned native Mirror depends on its learning; independent gifts/copies do not. */
export function captureAwakenedMirrorScope(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  phaseCurrent: () => boolean,
): (() => boolean) | null {
  const owner = captureAwakenedOwner(world, actorId, phaseCurrent),
    learned = owner?.state.learned,
    skill = learned?.skill;
  if (
    !owner ||
    currentAwakenedNight(world, owner.role) !== day ||
    !learned ||
    learned.role !== Role.MirrorGirl ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    day < learned.activeFromNight ||
    skill?.kind !== "inspection" ||
    skill.abilityId !== ability.id
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    abilityId = skill.abilityId;
  return () =>
    owner.isCurrent() &&
    currentAwakenedNight(world, owner.role) === day &&
    owner.state.learned === learned &&
    learned.skill === skill &&
    skill.kind === "inspection" &&
    skill.abilityId === abilityId &&
    learned.targetId === targetId &&
    learned.role === role &&
    learned.day === learnedDay &&
    learned.activationNight === activationNight &&
    learned.activeFromNight === activeFromNight &&
    findNightAbility(owner.role, "role_check", abilityId) === ability;
}
const nights = new WeakMap<
  World,
  { day: number; owners: Map<RoleComponent, AwakenedOwnerScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function beginAwakenedNight(
  world: World,
  day: number,
  owners: readonly AwakenedOwnerScope[],
): void {
  if (hasAwakenedNightCommit(world, day)) throw new Error("awakened_night_reentry_after_commit");
  if (nights.get(world)?.day === day) throw new Error("awakened_night_reentry_after_commit");
  if ((nights.get(world)?.day ?? day) > day) throw new Error("awakened_night_clock_regressed");
  const currentOwners = owners.filter((owner) => owner.world === world && owner.isCurrent());
  nights.set(world, { day, owners: new Map(currentOwners.map((owner) => [owner.role, owner])) });
  // Establishing this night's original-body authority is itself a committed prefix,
  // including nights with only an inherited base knife or no copied active skill.
  if (currentOwners.length) recordAwakenedNightCommit(world, day);
}
export function currentAwakenedNight(world: World, role: RoleComponent): number | null {
  const night = nights.get(world),
    owner = night?.owners.get(role);
  return night && owner?.isCurrent() && livingNightLife(world, owner.life) ? night.day : null;
}
export function recordAwakenedNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function hasAwakenedNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

/**
 * 负责觉醒隐狼开夜、学习、技能、额外刀和激活阶段。
 * 输入为原 native/copy scope 与已验证工具；输出为原已付事实及有来源的盾、刀和原毒 intent。
 * 复用原捕获 life/day/目标，保留付款位置以及允许首次死亡的 paid callback。
 * 不以新来源数据替代资格、库存或重试规则，不恢复撤销的原 owner，不改变阶段优先级或归档。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  awakenedNightIntent,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { allNightAbilities, findNightAbility, retiredNightAbilityIds } from "../abilities";
import { installNativeAbility } from "../ability_changes";
import { setNightAbilityStartDay } from "../abilities";
import { canAwakenedKnife } from "./inheritance";
import {
  beginAwakenedNight,
  bindAwakenedSkill,
  captureAwakenedOwner,
  currentAwakenedNight,
  recordAwakenedNightCommit,
} from "./night_scope";
import {
  activateAwakenedLearning,
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  chooseAwakenedAttack,
  chooseAwakenedGuard,
  closeAwakenedMimic,
  learnAwakenedRole,
  skipAwakenedSkill,
  useAwakenedPoison,
} from "./state";

function owners(ctx: NightStageContext, day: number, opening = false) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureAwakenedOwner(
      ctx.world,
      id,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    return owner && (opening || currentAwakenedNight(ctx.world, owner.role) === day) ? [owner] : [];
  });
}
const targets = (ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) =>
  new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
const effects = (ctx: NightStageContext) =>
  (ctx.state.awakenedEffects ??= { shields: [], attacks: [] });
const retry = (attempt: number) => (attempt ? { retry_attempt: attempt, retry_max: 2 } : {});

const openingStage: NightStageHandler = {
  id: "awakened_opening",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    beginAwakenedNight(ctx.world, day, owners(ctx, day, true));
  },
};
const mimicStage: NightStageHandler = {
  id: "awakened_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      if (!canAwakenedMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        const candidates = targets(ctx, owner.actorId, true);
        const roles = new Map(
          [...candidates.keys()].map((id) => {
            const component = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component, role: component.role, camp: component.camp }] as const;
          }),
        );
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["awakened_mimic"], {
                stage: "awakened_mimic",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...retry(attempt),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        if (action === null) {
          closeAwakenedMimic(owner.state, day);
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "awakened_mimic") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !canAwakenedMimic(owner.state, day) ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "awakened_mimic"
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          origin = roles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !origin ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== origin.component ||
          origin.component.role !== origin.role ||
          origin.component.camp !== origin.camp
        )
          continue;
        if (!learnAwakenedRole(owner.state, targetId, origin.role, day)) continue;
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimicked",
          payload: { actorId: owner.actorId, day, targetId, role: owner.state.learned!.role },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canAwakenedMimic(owner.state, day)) {
        if (targets(ctx, owner.actorId, true).size)
          throw new Error("awakened_mimic_valid_action_missing");
        closeAwakenedMimic(owner.state, day);
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimic_skipped",
          payload: { actorId: owner.actorId, day },
        });
      }
    }
  },
};

const skillStage: NightStageHandler = {
  id: "awakened_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day),
        skill = bound?.skill;
      if (!bound || !skill || skill.kind === "wolf") continue;
      const tool: ToolName = skill.kind === "poison" ? "awakened_poison" : "awakened_guard";
      const current = () => bound.isCurrent() && awakenedSkillForNight(owner.state, day) === skill;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "awakened_skill",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        if (action === null) {
          if (!skipAwakenedSkill(owner.state, day)) break;
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (call.name !== "awakened_poison" && call.name !== "awakened_guard") continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "awakened_poison" && skill.kind === "poison" && target) {
          if (!useAwakenedPoison(owner.state, day)) break;
          (ctx.state.poisonClaims ??= []).push(
            originalPoisonIntent(
              {
                source: owner.life,
                target,
                isCurrent: () => bound.isCurrent(true),
              },
              {
                family: "awakened",
                day,
                stage: "awakened_skill",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "awakened_guard" && skill.kind === "guard") {
          if (!chooseAwakenedGuard(owner.state, targetId, day)) continue;
          if (target)
            effects(ctx).shields.push(
              awakenedNightIntent(
                "awakened-shield",
                {
                  actorId: owner.actorId,
                  target,
                  isCurrent: () => bound.isCurrent(true),
                },
                {
                  family: "awakened",
                  day,
                  stage: "awakened_skill",
                  actorLife: owner.life,
                  requestedTargetId: targetId,
                  abilityId: "learned:awakened",
                },
              ),
            );
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId },
          });
        } else continue;
        recordAwakenedNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "awakened_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day);
      if (bound?.skill.kind !== "wolf") continue;
      const effectCurrent = () => bound.isCurrent() && canAwakenedKnife(owner.role, ctx.world);
      const current = () => effectCurrent() && canAwakenedExtraKnife(owner.state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["awakened_attack"], {
            stage: "awakened_attack",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "awakened_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "awakened_attack") continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (!chooseAwakenedAttack(owner.state, targetId, day)) break;
        if (target)
          effects(ctx).attacks.push(
            awakenedNightIntent(
              "awakened-attack",
              { actorId: owner.actorId, target, isCurrent: effectCurrent },
              {
                family: "awakened",
                day,
                stage: "awakened_attack",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_attack_valid_action_missing");
    }
  },
};

const activationStage: NightStageHandler = {
  id: "awakened_activation",
  priority: 900,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const learned = owner.state.learned;
      if (!learned || learned.activationNight !== null || !owner.isCurrent()) continue;
      let abilityId: string | undefined;
      if (learned.skill.kind === "inspection") {
        if (
          allNightAbilities(owner.role).some(
            (ability) => ability.kind === "role_check" && ability.source.kind === "native",
          ) ||
          retiredNightAbilityIds(owner.role).some((id) => id.startsWith("native:role_check"))
        )
          throw new Error("awakened_mirror_native_binding_conflict");
        installNativeAbility(owner.role, "role_check", {
          policy: "mirror",
          lastTarget: null,
          lastDay: null,
          history: [],
        });
        const ability = findNightAbility(owner.role, "role_check")!;
        setNightAbilityStartDay(ability, day + 1);
        abilityId = ability.id;
      }
      if (
        !owner.isCurrent() ||
        owner.state.learned !== learned ||
        !activateAwakenedLearning(owner.state, day, abilityId)
      )
        throw new Error("awakened_activation_commit_invalid");
      recordAwakenedNightCommit(ctx.world, day);
      ctx.events.push({
        timestamp: Date.now(),
        type: "awakened_ready",
        payload: {
          actorId: owner.actorId,
          activationNight: day,
          activeFromNight: day + 1,
          role: learned.role,
        },
      });
    }
  },
};

export const AWAKENED_NIGHT_STAGES = [
  openingStage,
  mimicStage,
  skillStage,
  attackStage,
  activationStage,
];

