/**
 * 负责觉醒隐狼的工具资格校验贡献。输入为原工具参数、角色状态及可信窗口，输出原规则拒绝或通过。
 * 当前原体、学习／盾／刀资格仍归实际机制，本校验不执行学习、消费库存或提交死亡。
 */
import { AWAKENED_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { isAliveTarget, type ToolRule, type ToolRuleMap } from "../../validation/contracts";
import { canAwakenedKnife } from "./inheritance";
import { currentAwakenedNight } from "./night_scope";
import {
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  getAwakenedState,
} from "./state";

const validateAwakened: ToolRule = ({ world, actorId, role, phase, day, toolCall }) => {
  const state = getAwakenedState(role);
  if (
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    day === undefined ||
    currentAwakenedNight(world, role) !== day
  )
    return { code: RuleError.AwakenedUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "awakened_mimic") {
    if (!canAwakenedMimic(state, day)) return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  const skill = awakenedSkillForNight(state, day);
  if (toolCall.name === "awakened_attack") {
    if (!canAwakenedKnife(role, world) || !canAwakenedExtraKnife(state, day))
      return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  if (toolCall.name === "awakened_poison" && skill?.kind === "poison")
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  if (toolCall.name === "awakened_guard" && skill?.kind === "guard") {
    if (toolCall.args.target_id !== null && !isAliveTarget(world, toolCall.args.target_id))
      return { code: RuleError.AwakenedTarget };
    if (
      toolCall.args.target_id !== null &&
      skill.lastTarget === toolCall.args.target_id &&
      skill.lastGuardDay === day - 1
    )
      return { code: RuleError.AwakenedGuardRepeat };
    return null;
  }
  return { code: RuleError.AwakenedUnavailable };
};
export { AWAKENED_TOOL_NAMES } from "./tool_names";
export const AWAKENED_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  AWAKENED_TOOL_NAMES.map((name) => [name, validateAwakened]),
);

/**
 * 负责熊的夜间采样 frame 与延迟到天亮的发布。输入为原相邻玩家和采样吼声；只有匹配原 frame 时才产生历史与天亮事件。不重复发布同一夜，不以复活或替换相邻身体继续旧采样；关闭和失败保持原前缀。
 */
import {
  recordBearRoar,
  bearDataField as ownData,
  bearDataArrayAppendable as appendable,
  bearHistoryUnpublished as unpublishedHistory,
  recordDawnBearRoar,
} from "./state";

import type { BearReadState as BearState } from "@ai-werewolf-arena/game-contract";

import {
  AliveComponent,
  aliveLifeVersion,
  aliveLifeDescriptor,
} from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { IdentityComponent } from "../../../../core/domain/entities/player";
import { Camp, Role, type GameEvent, type EntityId } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { getBearState } from "./state";
import { BEAR_SIGNAL_POLICIES, type BearSignalPolicy } from "@ai-werewolf-arena/game-contract";
import {
  captureOriginalPlayer,
  originalPlayerSameLife,
  type OriginalPlayerScope,
} from "../original_player_scope";
import type { CampComponent } from "../../../../core/domain/components/camp";
/** 同一 World／夜号的黎明发表状态：checking 只允许当前尝试，重入会撤销它；
 * 成功后 published，未完成则 finally 置 revoked。清空原 state.history 不恢复这一原发布许可。 */
const dawnPublications = new WeakMap<
  World,
  Map<number, { status: "checking" | "published" | "revoked" }>
>();
const now = Date.now.bind(Date);

function sampleRoar(world: World, actorId: EntityId, catalog: RoleCatalog): boolean {
  const ring = world
      .getAliveEntityIds()
      .sort(
        (a, b) =>
          (world.getComponent(a, COMPONENT.Identity)?.seat ?? a) -
            (world.getComponent(b, COMPONENT.Identity)?.seat ?? b) || a - b,
      ),
    index = ring.indexOf(actorId),
    neighbors =
      index < 0 || ring.length < 2
        ? []
        : [
            ...new Set([
              ring[(index + ring.length - 1) % ring.length],
              ring[(index + 1) % ring.length],
            ]),
          ];
  return neighbors.some((id) => {
    const target = world.getComponent(id, COMPONENT.Role);
    return (
      target?.camp === Camp.Wolf &&
      (catalog.runtime(target.role)?.detectableByBear?.(world, target) ?? true)
    );
  });
}

/** 快照由 manager 持有，不放在玩家 component 或 DTO 中。 */
export class BearNightFrame {
  /** 保留原 World、Role、state、Alive／Camp 与名单的实例引用及生命版本，不克隆为玩家 DTO。
   * 默认政策捕获夜初吼声；显式黎明政策保留原体名单和 catalog，在真正发表时才重新采样并复验。 */
  private constructor(
    private readonly owner: World,
    private readonly day: number,
    private readonly actorId: EntityId,
    private readonly role: RoleComponent,
    private readonly state: BearState,
    private readonly life: AliveComponent,
    private readonly lifeVersion: number,
    private readonly wasAlive: boolean,
    private readonly sampledRoar: boolean,
    private readonly signalPolicy: BearSignalPolicy,
    private readonly catalog: RoleCatalog,
    private readonly originals: readonly OriginalPlayerScope[],
    private readonly camp: CampComponent | undefined,
  ) {}

  static capture(
    world: World,
    day: number,
    catalog: RoleCatalog = getDefaultRoleCatalog(),
    signalPolicy: BearSignalPolicy = "awa_night_open_v1",
  ): BearNightFrame | null {
    if (!BEAR_SIGNAL_POLICIES.includes(signalPolicy)) throw Error("bear_signal_policy_invalid");
    const bears = world
      .entityIds()
      .filter((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Bear);
    if (bears.length > 1) throw new Error("bear_count_exceeds_limit");
    const actorId = bears[0];
    if (actorId === undefined) return null;
    const role = world.getComponent(actorId, COMPONENT.Role)!,
      state = getBearState(role),
      life = world.getComponent(actorId, COMPONENT.Alive),
      version = life && aliveLifeVersion(life);
    if (role.camp !== Camp.Good || !state || !life || version === undefined) return null;
    const originals =
        signalPolicy === "netease_dawn_live_v1"
          ? world.getAliveEntityIds().map((id) => captureOriginalPlayer(world, id))
          : [],
      camp = world.getComponent(actorId, COMPONENT.Camp);
    if (
      originals.some((p) => p === null) ||
      (signalPolicy === "netease_dawn_live_v1" && camp?.camp !== Camp.Good)
    )
      return null;
    const roared =
      signalPolicy === "awa_night_open_v1" ? sampleRoar(world, actorId, catalog) : false;
    return new BearNightFrame(
      world,
      day,
      actorId,
      role,
      state,
      life,
      version,
      life.alive,
      roared,
      signalPolicy,
      catalog,
      originals as OriginalPlayerScope[],
      camp,
    );
  }

  /** 完整夜死亡波后、该波判胜前发表。 */
  publish(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (this.signalPolicy === "netease_dawn_live_v1") {
      this.publishDawn(world, events, isCurrent);
      return;
    }
    if (
      world !== this.owner ||
      !isCurrent() ||
      world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      this.role.role !== Role.Bear ||
      this.role.camp !== Camp.Good ||
      getBearState(this.role) !== this.state ||
      world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      aliveLifeVersion(this.life) !==
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) ||
      this.state.history.some((report) => report.day === this.day)
    )
      return;
    const report = { day: this.day, roared: this.life.alive && this.wasAlive && this.sampledRoar };
    recordBearRoar(this.state, report);
    events.push({ timestamp: Date.now(), type: "bear_roared", payload: { ...report } });
  }
  private dawnBodyCurrent(world: World): boolean {
    const factory = aliveLifeDescriptor(this.life);
    if (!factory) return false;
    const actual = Object.getOwnPropertyDescriptor(this.life, "alive"),
      history = ownData(this.state, "history");
    return (
      actual?.get === factory.get &&
      actual?.set === factory.set &&
      world.getComponent(this.actorId, COMPONENT.Role) === this.role &&
      ownData(this.role, "role") === Role.Bear &&
      ownData(this.role, "camp") === Camp.Good &&
      ownData(ownData(this.role, "privateState"), "bear") === this.state &&
      world.getComponent(this.actorId, COMPONENT.Alive) === this.life &&
      aliveLifeVersion(this.life) ===
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) &&
      world.getComponent(this.actorId, COMPONENT.Camp) === this.camp &&
      ownData(this.camp, "camp") === Camp.Good &&
      this.originals.every((p) => originalPlayerSameLife(world, p, true)) &&
      world.getAliveEntityIds().every((id) => this.originals.some((p) => p.id === id)) &&
      unpublishedHistory(history, this.day)
    );
  }
  private publishDawn(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (world !== this.owner) return;
    let publications = dawnPublications.get(world);
    if (!publications) {
      publications = new Map();
      dawnPublications.set(world, publications);
    }
    const prior = publications.get(this.day);
    if (prior) {
      if (prior.status === "checking") prior.status = "revoked";
      return;
    }
    const lease: { status: "checking" | "published" | "revoked" } = { status: "checking" };
    publications.set(this.day, lease);
    try {
      if (!isCurrent() || !this.dawnBodyCurrent(world)) return;
      const before = this.originals.map((p) => ({
          p,
          version: aliveLifeVersion(p.life),
          identity: world.getComponent(p.id, COMPONENT.Identity),
          seat: ownData(world.getComponent(p.id, COMPONENT.Identity), "seat"),
        })),
        sampled =
          this.life.alive && this.wasAlive ? sampleRoar(world, this.actorId, this.catalog) : false;
      if (
        !isCurrent() ||
        lease.status !== "checking" ||
        !this.dawnBodyCurrent(world) ||
        before.some(
          ({ p, version, identity, seat }) =>
            aliveLifeVersion(p.life) !== version ||
            world.getComponent(p.id, COMPONENT.Identity) !== identity ||
            ownData(identity, "seat") !== seat,
        )
      )
        return;
      const history = ownData(this.state, "history");
      if (history === events || !appendable(history) || !appendable(events)) return;
      const report = { day: this.day, roared: this.life.alive && this.wasAlive && sampled },
        event: GameEvent = { timestamp: now(), type: "bear_roared", payload: { ...report } };
      // 两个原受控数组按事件→历史写入；原生 defineProperty 不执行数组元素 setter。
      // 这不是事务：第二次写抛错时第一事件保留，finally 只撤销尚 checking 的发布状态，不回滚数组。
      Object.defineProperty(events, String(events.length), {
        value: event,
        enumerable: true,
        writable: true,
        configurable: true,
      });
      recordDawnBearRoar(history, report);
      lease.status = "published";
    } finally {
      if (lease.status === "checking") lease.status = "revoked";
    }
  }
}

/**
 * 负责黑市商人在后置受赠行动之前的交易阶段。输入为当前商人库存与已验证的技能／收货选择；
 * 输出为独立受赠能力或赠枪、反噬提案和跳过／提交事实。已付效果仍绑定原生命，不转给替换商人。
 */
import { closeBlackMarketTrade, recordBlackMarketTrade } from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { grantDeathGun } from "../death_abilities";
import { recipientAbilityStage } from "../recipient_ability_stage";
import { canBlackMarketTrade, getBlackMarketState } from "./state";
const committed = new WeakMap<World, Set<number>>();
export function hasBlackMarketNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export const BLACK_MARKET_RECIPIENT_STAGE = recipientAbilityStage("black_market", 140);
export const BLACK_MARKET_TRADE_STAGE: NightStageHandler = {
  id: "black_market_merchant",
  priority: 130,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.BlackMarketMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getBlackMarketState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || role.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = (paid = false) =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.BlackMarketMerchant &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getBlackMarketState(role) === state &&
        (livingNightLife(ctx.world, life) ||
          (paid &&
            ctx.world.getComponent(actorId, COMPONENT.Alive) === life.life &&
            !life.life.alive &&
            aliveLifeVersion(life.life) === life.version + 1));
      const current = () => ownerCurrent() && canBlackMarketTrade(state, day);
      if (!current()) continue;
      const skip = () => {
        closeBlackMarketTrade(state, day);
        recordCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_skipped",
          payload: { actorId, day },
        });
      };
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: targetRole.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["black_market_trade"], {
                stage: "black_market_merchant",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          skip();
          completed = true;
          break;
        }
        if (action.name !== "black_market_trade") continue;
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !validated.ok || validated.sanitizedCall?.name !== "black_market_trade")
          continue;
        const { target_id: targetId, skill } = validated.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          target.role.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        if (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
          throw new Error("black_market_target_camp_unsupported");
        const failed = target.camp === Camp.Wolf;
        if (!failed) {
          if (skill === "gun") grantDeathGun(ctx.world, actorId, targetId, day, ctx.events);
          else {
            const base = {
              id: "gift:black-market",
              activation: "black_market" as const,
              source: { kind: "gift" as const, actorId },
              sourceDisclosed: false,
              startsOnDay: day + 1,
              maxUses: 1,
            };
            if (skill === "check")
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "seer_check",
                  state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
                },
                ctx.events,
              );
            else
              grantNightAbility(
                ctx.world,
                targetId,
                {
                  ...base,
                  kind: "potion",
                  state: {
                    heal: 0,
                    poison: 1,
                    selfHealRule: WitchSelfHealRule.Disabled,
                    canSelfHeal: false,
                    healUsedThisNight: false,
                    poisonUsedThisNight: false,
                  },
                },
                ctx.events,
              );
          }
        }
        recordBlackMarketTrade(state, day, targetId, skill);
        recordCommit(ctx.world, day);
        const choice = state.choice!;
        if (failed)
          (ctx.state.blackMarketBacklashes ??= []).push({
            target: life,
            isCurrent: () =>
              ownerCurrent(true) &&
              state.choice === choice &&
              choice.day === day &&
              choice.targetId === targetId &&
              choice.skill === skill,
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "black_market_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failed ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) {
        if (ctx.world.getAliveEntityIds().some((id) => id !== actorId))
          throw new Error("black_market_valid_action_missing");
        skip();
      }
    }
  },
};

