  presentation: nativeRolePresentation("mechanical_wolf"),
};

/**
 * 负责机械狼工具的本夜模式与行动资格校验。输入为原工具参数、角色状态及可信上下文，输出原规则拒绝或通过。
 * 预检不等于复制、付款或落效果，原体与能力资源仍由机械机制持有并在提交时复验。
 */
import { MECHANICAL_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { ToolRule, ToolRuleMap } from "../../validation/contracts";
import { isAliveTarget } from "../../validation/contracts";
import { canMechanicalKnife } from "./inheritance";
import { hasCurrentMechanicalMode } from "./night_scope";
import {
  canMechanicalMimic,
  canSelectMechanicalMode,
  canMechanicalExtraKnife,
  getMechanicalState,
  mechanicalSkillForNight,
} from "./state";

const validateMechanical: ToolRule = ({ world, actorId, role, day, phase, toolCall }) => {
  const state = getMechanicalState(role);
  if (role.role !== Role.MechanicalWolf || role.camp !== Camp.Wolf || !state || day === undefined)
    return { code: RuleError.MechanicalUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "mechanical_mode") {
    return canSelectMechanicalMode(state, day) && ["kill", "skill"].includes(toolCall.args.mode)
      ? null
      : { code: RuleError.MechanicalUnavailable };
  }
  if (toolCall.name === "mimic_role") {
    if (!canMechanicalMimic(state, day)) return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_attack") {
    if (!canMechanicalKnife(role, world) || !canMechanicalExtraKnife(state, day))
      return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  const skill = hasCurrentMechanicalMode(world, role, "skill")
    ? mechanicalSkillForNight(state, day)
    : undefined;
  if (toolCall.name === "mechanical_inspect" && skill?.kind === "inspection") {
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_poison" && skill?.kind === "poison" && skill.remaining > 0) {
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_guard" && skill?.kind === "guard") {
    // 连续守护同编号仍是合法提交；惩罚在黎明生效，不能在预检阶段代付或拒绝。
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  return { code: RuleError.MechanicalUnavailable };
};

export { MECHANICAL_TOOL_NAMES } from "./tool_names";
export const MECHANICAL_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  MECHANICAL_TOOL_NAMES.map((name) => [name, validateMechanical]),
);

/**
 * 负责奇迹商人从实际库存选择赠予。输入为当前原体和已验证的技能／收货选择；
 * 输出为实际拥有的赠予、反噬提案和跳过／提交事实。已付提案保留原生命资格，不转给替换赠予者。
 */
import { closeMerchantTrade, recordMerchantTrade } from "./state";

import type { MiracleSkill } from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, Phase, WitchSelfHealRule } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { grantNightAbility } from "../night-ability-grants";
import { canMerchantTrade, getMerchantState } from "./state";

const committed = new WeakMap<World, Set<number>>();
export function hasMerchantNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
function recordCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

export const MIRACLE_MERCHANT_STAGE: NightStageHandler = {
  id: "miracle_merchant",
  priority: 125,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const actorId of ctx.getAliveByRole(Role.MiracleMerchant)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getMerchantState(role),
        life = captureNightLife(ctx.world, actorId);
      if (!state || !life || role.camp !== Camp.Good) continue;
      const privateState = role.privateState;
      const ownerCurrent = () =>
        ctx.isCurrent() &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.MiracleMerchant &&
        role.camp === Camp.Good &&
        role.privateState === privateState &&
        getMerchantState(role) === state &&
        livingNightLife(ctx.world, life);
      const current = () => ownerCurrent() && canMerchantTrade(state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: targetRole.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        const action = targets.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, ["bestow_ability"], {
                stage: "miracle_merchant",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!current()) break;
        if (action === null) {
          closeMerchantTrade(state, day);
          recordCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "merchant_trade_skipped",
            payload: { actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "bestow_ability") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "bestow_ability") continue;
        const { target_id: targetId, skill } = valid.sanitizedCall.args,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          target.role.camp !== target.camp ||
          target.role.privateState !== target.privateState
        )
          continue;
        const failure = target.camp === Camp.Wolf;
        if (!failure) {
          const base = {
            id: "gift:miracle",
            activation: "lucky" as const,
            source: { kind: "gift" as const, actorId },
            sourceDisclosed: false,
            startsOnDay: day,
            maxUses: 1,
          };
          if (skill === "check")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "seer_check",
                state: { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] },
              },
              ctx.events,
            );
          if (skill === "guard")
            grantNightAbility(
              ctx.world,
              targetId,
              { ...base, kind: "guard", state: { lastTarget: null } },
              ctx.events,
            );
          if (skill === "poison")
            grantNightAbility(
              ctx.world,
              targetId,
              {
                ...base,
                kind: "potion",
                state: {
                  heal: 0,
                  poison: 1,
                  selfHealRule: WitchSelfHealRule.Disabled,
                  canSelfHeal: false,
                  healUsedThisNight: false,
                  poisonUsedThisNight: false,
                },
              },
              ctx.events,
            );
        }
        recordMerchantTrade(state, day, targetId, skill as MiracleSkill);
        recordCommit(ctx.world, day);
        if (failure)
          (ctx.state.merchantBacklashes ??= []).push({ target: life, isCurrent: ownerCurrent });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_committed",
          payload: { actorId, day, targetId, skill },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "merchant_trade_resolved",
          payload: { actorId, day, targetId, skill, outcome: failure ? "backlash" : "granted" },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("merchant_valid_action_missing");
    }
  },
};

/**
 * 负责 奇迹商人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import {
  getMerchantState,
  freshMerchantState,
  setMerchantState,
  projectMerchantState,
  canMerchantTrade,
} from "./state";
import { MIRACLE_MERCHANT_STAGE } from "./night_stage";
import { LUCKY_ABILITY_STAGE } from "./lucky_stage";

export const MIRACLE_MERCHANT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.MiracleMerchant,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("miracle_merchant"),
    skillBrief: text("zh-CN", "role.miracle_merchant.brief"),
    supportedBoardRoles: [
      Role.CursedFox,
      Role.MiracleMerchant,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
