          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, skill: args.skill };
        },
      },
    },
    baselineAction: (_role, request, pick) => {
      if (!request.allowedTools.includes("bestow_ability")) return null;
      const target = pick();
      return target === null
