      id,
      role,
      roleName,
      camp,
      campComponent,
      privateState,
      identity,
      identityFields: ["id", "seat", "name", "sessionId"].map((k) => data(identity, k)),
      life,
      version: aliveLifeVersion(life)!,
      abilitiesCurrent: bindNativeAbilities(privateState),
    });
  }
