    caster = b.latestCasters.get(b.alchemistId);
  if (
    n.handedOff ||
    n.mistDecided ||
    !n.lives.has(b.alchemistId) ||
    !caster?.isCurrent() ||
    (caster.state() as AlchemistState).mistRemaining === 0
  )
    return [];
