  const state = b.latestCasters.get(b.alchemistId)!.commitMist(targets, legal);
  const chosen = state.mistHistory.at(-1)!.targetIds;
  n.mistTargets = chosen === null ? null : Object.freeze(chosen.map((id) => n.lives.get(id)!));
