      nobleState as NobleState,
      bodyState as SecretBodyState,
      nobleData,
      bodyData,
    ),
    contracts: new Map(),
    nights: new Map(),
    active: null,
    checkingController: false,
    nobleKnowledge: copyNobleKnowledge({
