export function beginNobleBodyNight(
  world: World,
  day: number,
  isCurrent: () => boolean,
  nightUnit?: NightUnit,
): readonly NobleBodyNightNotice[] {
  // 新自有身份必须属于本次真实夜；旧两参数／三参数调用不增加元数据读取。
