  if (
    !Number.isSafeInteger(day) ||
    day < 1 ||
    day >= Number.MAX_SAFE_INTEGER - 1 ||
    !mayBegin(owner, day) ||
    typeof isCurrent !== "function" ||
    types.isProxy(isCurrent) ||
    !checkController(owner, isCurrent)
