      wolfActionPolicy: owner.stateSlot.nobleState.wolfActionPolicy,
      lastNotifiedNight: day,
      lastChoice: owner.stateSlot.nobleState.lastChoice,
      contracts: owner.stateSlot.nobleState.contracts,
