export function eclipseChoiceEligible(world: World, day: number, actorId: number): boolean {
  try {
    const { b, n } = requireNight(world, day);
    return (
      day >= 2 &&
      actorId === b.maidId &&
      current(world, b.players.get(actorId)!, false) &&
      n.swallowOpened &&
      !n.swallowed
